	async function deleteCurrentPicture(uid, field) {
		if (meta.config['profile:keepAllUserImages']) {
			return;
		}
		const value = await db.getObjectField(`user:${uid}`, field);
		const type = field === 'cover:url' ? 'cover' : 'avatar';
		const uploadPath = await getLocalProfileImagePath(uid, type, value);
		await file.delete(uploadPath);
	}

	function validateUpload(data, maxSize, allowedTypes) {
		if (!data.imageData) {
			throw new Error('[[error:invalid-data]]');
		}
		const size = image.sizeFromBase64(data.imageData);
		if (size > maxSize * 1024) {
			throw new Error(`[[error:file-too-big, ${maxSize}]]`);
		}

		const type = image.mimeFromBase64(data.imageData);
		if (!type || !allowedTypes.includes(type)) {
			throw new Error('[[error:invalid-image]]');
		}
	}

	async function convertToPNG(path) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		if (!convertToPNG) {
			return path;
		}
		const newPath = await image.normalise(path);
		await file.delete(path);
		return newPath;
	}

	function generateProfileImageFilename(uid, extension) {
		const convertToPNG = meta.config['profile:convertProfileImageToPNG'] === 1;
		return `${uid}-profileavatar-${Date.now()}${convertToPNG ? '.png' : extension}`;
	}

	User.getLocalCoverPath = async function (uid) {
		const url = await db.getObjectField(`user:${uid}`, 'cover:url');
		return await getLocalProfileImagePath(uid, 'cover', url) || false;
	};

	User.getLocalAvatarPath = async function (uid) {
		const url = await db.getObjectField(`user:${uid}`, 'uploadedpicture');
		return await getLocalProfileImagePath(uid, 'avatar', url) || false;
	};

	User.removeProfileImage = async function (uid) {
		if (!isValidUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}

		const userData = await db.getObjectFields(`user:${uid}`, ['uploadedpicture', 'picture']);
		const previousValues = {
			uploadedpicture: userData.uploadedpicture,
			picture: userData.picture,
		};

		const uploadPath = await getLocalProfileImagePath(uid, 'avatar', userData.uploadedpicture);
		await file.delete(uploadPath);

		const fields = { uploadedpicture: '' };
		if (userData.picture === userData.uploadedpicture) {
			fields.picture = '';
		}
		await User.setUserFields(uid, fields);

		return previousValues;
	};

	User.removeCoverPicture = async function (uid) {
		if (!isValidUid(uid)) {
			throw new Error('[[error:invalid-uid]]');
		}

		const coverUrl = await db.getObjectField(`user:${uid}`, 'cover:url');
		const uploadPath = await getLocalProfileImagePath(uid, 'cover', coverUrl);
		await file.delete(uploadPath);
		await db.deleteObjectFields(`user:${uid}`, ['cover:url', 'cover:position']);

		return { success: true };
	};

	async function getLocalProfileImagePath(uid, type, url) {
		if (!isValidUid(uid) || typeof url !== 'string') {
			return false;
		const followingSets = followers.map(uid => `following:${uid}`);
		const followerSets = following.map(uid => `followers:${uid}`);

		await Promise.all([
			db.sortedSetsRemove(followerSets.concat(followingSets), uid),
			updateCount(following, 'followers:', 'followerCount'),
			updateCount(followers, 'following:', 'followingCount'),
		]);
	}

	async function deleteImages(uid) {
		const folder = path.resolve(nconf.get('upload_path'), 'profile');
		let filenames;
		try {
			filenames = await fs.promises.readdir(folder);
		} catch (err) {
			if (err.code === 'ENOENT') {
				return;
			}
			throw err;
		}

		const extensions = ['png', 'jpeg', 'jpg', 'bmp', ...User.getAllowedProfileImageExtensions()];
		const extensionPattern = [...new Set(extensions)].map(ext => ext.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
		const uidPattern = String(uid).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
		const imagePattern = new RegExp(`^${uidPattern}-profile(?:cover|avatar)(?:-\\d+)?\\.(?:${extensionPattern})$`, 'i');
		const imagePaths = filenames.filter(filename => imagePattern.test(filename)).map(filename => path.join(folder, filename));
		await Promise.all(imagePaths.map(file.delete));
	}
